    "CREATE TRIGGER IF NOT EXISTS app_works_gone AFTER DELETE ON works BEGIN INSERT INTO app_changes (id, seq, floor) VALUES (1, 1, 0) ON CONFLICT (id) DO UPDATE SET seq = seq + 1; INSERT INTO app_gone (work_id, seq, gone_at) VALUES (OLD.id, (SELECT seq FROM app_changes WHERE id = 1), CAST(strftime('%s', 'now') AS INTEGER)) ON CONFLICT (work_id) DO UPDATE SET seq = excluded.seq, gone_at = excluded.gone_at; END",
