    'CREATE TRIGGER IF NOT EXISTS app_files_changed AFTER UPDATE ON files WHEN (OLD.role = \'book\' OR NEW.role = \'book\') AND (OLD."edition_id" IS NOT NEW."edition_id" OR OLD."library_id" IS NOT NEW."library_id" OR OLD."role" IS NOT NEW."role" OR OLD."size" IS NOT NEW."size" OR OLD."mtime_ns" IS NOT NEW."mtime_ns" OR OLD."sha256" IS NOT NEW."sha256" OR OLD."format" IS NOT NEW."format" OR OLD."part" IS NOT NEW."part" OR OLD."duration_ms" IS NOT NEW."duration_ms" OR OLD."missing_at" IS NOT NEW."missing_at") BEGIN INSERT INTO app_changes (id, seq, floor) VALUES (1, 0, 0) ON CONFLICT (id) DO NOTHING; UPDATE works SET change_seq = (SELECT seq FROM app_changes WHERE id = 1) + 1 + id - (SELECT min(id) FROM works WHERE id IN (SELECT work_id FROM editions WHERE id IN (OLD.edition_id, NEW.edition_id))) WHERE id IN (SELECT work_id FROM editions WHERE id IN (OLD.edition_id, NEW.edition_id)); UPDATE app_changes SET seq = seq + coalesce((SELECT max(id) - min(id) + 1 FROM works WHERE id IN (SELECT work_id FROM editions WHERE id IN (OLD.edition_id, NEW.edition_id))), 0) WHERE id = 1; END',
