    'CREATE TRIGGER IF NOT EXISTS app_credits_made AFTER INSERT ON credits BEGIN INSERT INTO app_changes (id, seq, floor) VALUES (1, 0, 0) ON CONFLICT (id) DO NOTHING; UPDATE works SET change_seq = (SELECT seq FROM app_changes WHERE id = 1) + 1 + id - (SELECT min(id) FROM works WHERE id IN (SELECT NEW.work_id UNION SELECT work_id FROM editions WHERE id = NEW.edition_id)) WHERE id IN (SELECT NEW.work_id UNION SELECT work_id FROM editions WHERE id = NEW.edition_id); UPDATE app_changes SET seq = seq + coalesce((SELECT max(id) - min(id) + 1 FROM works WHERE id IN (SELECT NEW.work_id UNION SELECT work_id FROM editions WHERE id = NEW.edition_id)), 0) WHERE id = 1; END',
