    'CREATE TRIGGER IF NOT EXISTS app_people_renamed AFTER UPDATE OF name ON people WHEN OLD.name IS NOT NEW.name BEGIN INSERT INTO app_changes (id, seq, floor) VALUES (1, 0, 0) ON CONFLICT (id) DO NOTHING; UPDATE works SET change_seq = (SELECT seq FROM app_changes WHERE id = 1) + 1 + id - (SELECT min(id) FROM works WHERE id IN (SELECT work_id FROM credits WHERE person_id = NEW.id AND work_id IS NOT NULL UNION SELECT e.work_id FROM credits c JOIN editions e ON e.id = c.edition_id WHERE c.person_id = NEW.id)) WHERE id IN (SELECT work_id FROM credits WHERE person_id = NEW.id AND work_id IS NOT NULL UNION SELECT e.work_id FROM credits c JOIN editions e ON e.id = c.edition_id WHERE c.person_id = NEW.id); UPDATE app_changes SET seq = seq + coalesce((SELECT max(id) - min(id) + 1 FROM works WHERE id IN (SELECT work_id FROM credits WHERE person_id = NEW.id AND work_id IS NOT NULL UNION SELECT e.work_id FROM credits c JOIN editions e ON e.id = c.edition_id WHERE c.person_id = NEW.id)), 0) WHERE id = 1; END',
